            # subprocesses.
            os.setpgid(sub_pid, sub_pid)

            remaining = time_limit
            notice('Start watching %s (%s)' % (sub_pid, remaining))
            timed_out = False
            while True:
                waited_pid, wait_status = os.waitpid(sub_pid, os.WNOHANG)
                if waited_pid == sub_pid:
                    if _read_job_result() is None:
                        jwrite(_job_result({
                            'failed': True,
                            'msg': 'async worker exited without writing a completed result',
                            'ansible_async_pid': sub_pid,
                            'ansible_async_exit_status': wait_status,
                        }, jid, 1, 1))
                    break
                if remaining <= 0:
                    notice('Now killing %s' % sub_pid)
                    try:
